-- Development-only PDF fixtures for the pre-seeded application history.
WITH sample_pdf AS (
    SELECT decode(
        '',
        'hex'
    ) AS content
)

INSERT INTO application_cv_snapshots (
    application_id,
    original_filename,
    content_type,
    file_data,
    file_size
)
SELECT
    seeded_applications.application_id,
    'sample-candidate-cv.pdf' AS original_filename,
    'application/pdf' AS content_type,
    sample_pdf.content AS file_data,
    594 AS file_size
FROM (VALUES (1), (2), (3), (4), (5)) AS seeded_applications(application_id)
CROSS JOIN sample_pdf
ON CONFLICT (application_id) DO NOTHING;
